-- DRAFT — NEAPLIKOVAT bez schválení majitelem (CLAUDE.md pravidlo 3). Jen DATA, žádné schéma.
-- FAQ „Jak vám mohu zanechat recenzi?“ (faq_items fa9603a9-a628-4349-9797-4c0bcc71fc57, published,
-- 8 jazyků; čte ho web /faq i AI agenti přes get_faq). Dnes odpověď vyjmenovává Google, Facebook,
-- Firmy.cz a Tripadvisor → majitel 2026-10-15: „odkaz na recenze by měl být vždy google“.
-- Nově: jen Google (odkaz = app_settings.google_review_url) + stejná možnost pro každého napsat
-- soukromě, co zlepšit (appka: tlačítko „Napiš nám přímo, co máme zlepšit“ u dokončené rezervace
-- → Velín Zprávy; bez appky e-mail). Neutrální formulace (žádné „pokud jste spokojeni“).
-- Aplikovat AŽ s vydáním appky s novou kartou hodnocení (text na ni odkazuje).
-- Idempotentní (čisté SET). Otázky (question) zůstávají beze změny. updated_at nastaví trigger.
-- Bez BEGIN/COMMIT: deploy-sql.yml spouští každý soubor v jedné transakci (psql --single-transaction).
-- Alternativa bez SQL: Velín → CMS → Texty webu → Časté dotazy → upravit odpověď (+ „Přeložit“).

UPDATE public.faq_items SET
  answer = $cs$Budeme moc rádi za tvou zpětnou vazbu. Recenzi nám můžeš napsat na <a href="https://g.page/r/CUmeYvk-sNf6EBM/review" target="_blank" rel="noopener"><span style="font-weight: bold;">Google</span></a> – stačí účet Google, ohodnotíš nás hvězdičkami a můžeš přidat krátký komentář.<div>Chceš nám napsat přímo, co máme zlepšit? V aplikaci MotoGo24 otevři dokončenou rezervaci, ohodnoť jízdu a klepni na <span style="font-weight: bold;">Napiš nám přímo, co máme zlepšit</span> – zpráva přijde jen našemu týmu a nikde se nezveřejní. Případně nám napiš na <a href="mailto:info@motogo24.cz">info@motogo24.cz</a>.</div>$cs$,
  translations = COALESCE(translations, '{}'::jsonb) || jsonb_build_object(
    'en', COALESCE(translations->'en', '{}'::jsonb) || jsonb_build_object('answer',
      $en$We'd love to hear your feedback. You can write us a review on <a href="https://g.page/r/CUmeYvk-sNf6EBM/review" target="_blank" rel="noopener"><span style="font-weight: bold;">Google</span></a> – all you need is a Google account: rate us with stars and add a short comment if you like.<div>Want to tell us directly what we can improve? In the MotoGo24 app, open a completed booking, rate your ride and tap <span style="font-weight: bold;">Tell us directly what we can improve</span> – the message goes only to our team and is never published. You can also write to <a href="mailto:info@motogo24.cz">info@motogo24.cz</a>.</div>$en$),
    'de', COALESCE(translations->'de', '{}'::jsonb) || jsonb_build_object('answer',
      $de$Wir freuen uns sehr über dein Feedback. Eine Bewertung kannst du uns auf <a href="https://g.page/r/CUmeYvk-sNf6EBM/review" target="_blank" rel="noopener"><span style="font-weight: bold;">Google</span></a> schreiben – du brauchst nur ein Google-Konto, vergibst Sterne und kannst einen kurzen Kommentar hinzufügen.<div>Möchtest du uns direkt sagen, was wir besser machen können? Öffne in der MotoGo24-App eine abgeschlossene Buchung, bewerte die Fahrt und tippe auf <span style="font-weight: bold;">Schreib uns direkt, was wir besser machen können</span> – die Nachricht geht nur an unser Team und wird nirgends veröffentlicht. Du kannst uns auch an <a href="mailto:info@motogo24.cz">info@motogo24.cz</a> schreiben.</div>$de$),
    'es', COALESCE(translations->'es', '{}'::jsonb) || jsonb_build_object('answer',
      $es$Nos encantará conocer tu opinión. Puedes escribirnos una reseña en <a href="https://g.page/r/CUmeYvk-sNf6EBM/review" target="_blank" rel="noopener"><span style="font-weight: bold;">Google</span></a>: solo necesitas una cuenta de Google, nos valoras con estrellas y, si quieres, añades un breve comentario.<div>¿Quieres decirnos directamente qué podemos mejorar? En la app MotoGo24 abre una reserva finalizada, valora el viaje y toca <span style="font-weight: bold;">Dinos directamente qué podemos mejorar</span>: el mensaje llega solo a nuestro equipo y nunca se publica. También puedes escribirnos a <a href="mailto:info@motogo24.cz">info@motogo24.cz</a>.</div>$es$),
    'fr', COALESCE(translations->'fr', '{}'::jsonb) || jsonb_build_object('answer',
      $fr$Ton avis nous fait très plaisir. Tu peux nous écrire un avis sur <a href="https://g.page/r/CUmeYvk-sNf6EBM/review" target="_blank" rel="noopener"><span style="font-weight: bold;">Google</span></a> – il suffit d'un compte Google : tu nous notes avec des étoiles et tu peux ajouter un court commentaire.<div>Tu veux nous dire directement ce qu'on peut améliorer ? Dans l'application MotoGo24, ouvre une réservation terminée, note ta balade et appuie sur <span style="font-weight: bold;">Dis-nous directement ce qu'on peut améliorer</span> – le message arrive uniquement à notre équipe et n'est jamais publié. Tu peux aussi nous écrire à <a href="mailto:info@motogo24.cz">info@motogo24.cz</a>.</div>$fr$),
    'nl', COALESCE(translations->'nl', '{}'::jsonb) || jsonb_build_object('answer',
      $nl$We horen graag wat je ervan vond. Je kunt een review voor ons schrijven op <a href="https://g.page/r/CUmeYvk-sNf6EBM/review" target="_blank" rel="noopener"><span style="font-weight: bold;">Google</span></a> – je hebt alleen een Google-account nodig, geeft ons sterren en kunt een korte opmerking toevoegen.<div>Wil je ons direct laten weten wat we kunnen verbeteren? Open in de MotoGo24-app een afgeronde boeking, beoordeel je rit en tik op <span style="font-weight: bold;">Laat ons direct weten wat we kunnen verbeteren</span> – het bericht gaat alleen naar ons team en wordt nergens gepubliceerd. Je kunt ons ook mailen via <a href="mailto:info@motogo24.cz">info@motogo24.cz</a>.</div>$nl$),
    'pl', COALESCE(translations->'pl', '{}'::jsonb) || jsonb_build_object('answer',
      $pl$Bardzo się ucieszymy z Twojej opinii. Recenzję możesz nam napisać w <a href="https://g.page/r/CUmeYvk-sNf6EBM/review" target="_blank" rel="noopener"><span style="font-weight: bold;">Google</span></a> – wystarczy konto Google, oceniasz nas gwiazdkami i możesz dodać krótki komentarz.<div>Chcesz napisać nam wprost, co możemy poprawić? W aplikacji MotoGo24 otwórz zakończoną rezerwację, oceń przejażdżkę i stuknij <span style="font-weight: bold;">Napisz nam wprost, co możemy poprawić</span> – wiadomość trafi tylko do naszego zespołu i nigdzie nie zostanie opublikowana. Możesz też napisać na <a href="mailto:info@motogo24.cz">info@motogo24.cz</a>.</div>$pl$),
    'uk', COALESCE(translations->'uk', '{}'::jsonb) || jsonb_build_object('answer',
      $uk$Ми будемо дуже раді твоєму відгуку. Написати нам відгук можна в <a href="https://g.page/r/CUmeYvk-sNf6EBM/review" target="_blank" rel="noopener"><span style="font-weight: bold;">Google</span></a> – потрібен лише обліковий запис Google: оціни нас зірками й за бажання додай короткий коментар.<div>Хочеш написати нам напряму, що варто покращити? У застосунку MotoGo24 відкрий завершене бронювання, оціни поїздку й натисни <span style="font-weight: bold;">Напиши нам напряму, що варто покращити</span> – повідомлення отримає лише наша команда, і його ніде не буде опубліковано. Також можеш написати на <a href="mailto:info@motogo24.cz">info@motogo24.cz</a>.</div>$uk$)
  )
WHERE id = 'fa9603a9-a628-4349-9797-4c0bcc71fc57';


